# Every function's output against inst/conformance/fixture.nt must exactly
# match its golden CSV. This is the parity contract a future Python port is
# built against (inst/conformance/README.md documents the exact format).
# Goldens are regenerated by scripts/040-build-goldens.R, never hand-edited.

conformance_dir <- system.file("conformance", package = "cybedtools")
if (!nzchar(conformance_dir)) {
  # Running against the source tree rather than an installed package
  # (devtools::load_all()); fall back to the checkout path.
  conformance_dir <- testthat::test_path("..", "..", "inst", "conformance")
}

skip_if_no_conformance_fixture <- function() {
  skip_if_not_installed("rdflib")
  skip_if_not(
    file.exists(file.path(conformance_dir, "fixture.nt")),
    "conformance fixture not found; run scripts/040-build-goldens.R"
  )
}

read_golden <- function(name) {
  readr::read_csv(
    file.path(conformance_dir, "goldens", paste0(name, ".csv")),
    col_types = readr::cols(.default = "c"),
    na = ""
  )
}

as_char_frame <- function(df) {
  df <- as.data.frame(lapply(df, as.character), stringsAsFactors = FALSE)
  df[is.na(df)] <- ""
  df
}

test_that("framework_metadata matches its golden", {
  skip_if_no_conformance_fixture()
  rdf <- rdflib::rdf_parse(file.path(conformance_dir, "fixture.nt"), format = "ntriples")

  result <- framework_metadata(rdf) |> dplyr::arrange(.data$framework)
  golden <- read_golden("framework_metadata")

  expect_equal(as_char_frame(result), as_char_frame(golden))
})

test_that("unit_element_bindings matches its golden", {
