test_that("framework_similarity matches its golden", {
  skip_if_no_conformance_fixture()
  rdf <- rdflib::rdf_parse(file.path(conformance_dir, "fixture.nt"), format = "ntriples")

  result <- framework_similarity(rdf, from = "fixture-wf1", to = "fixture-wf2", n = 5) |>
    dplyr::mutate(score = round(.data$score, 10)) |>
    dplyr::arrange(.data$from_unit, .data$rank)
  golden <- read_golden("framework_similarity") |>
    dplyr::mutate(rank = as.integer(.data$rank))

  expect_equal(nrow(result), nrow(golden))
  expect_equal(as.character(result$from_unit), golden$from_unit)
  expect_equal(as.character(result$to_unit),   golden$to_unit)
  expect_equal(as.numeric(result$score), as.numeric(golden$score), tolerance = 1e-9)
  expect_equal(as.character(result$strength), golden$strength)
  expect_equal(result$rank, golden$rank)
})

